<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import axios from 'axios'; import api from '../plugins/axios'
const route = useRoute(); const pedido = ref<any>(null); const error = ref(''); const mensaje = ref(''); const observacion = ref(''); const comprobante = ref(false); const cargando = ref(true)
async function cargar() { try { const { data } = await api.get(`/pedidos/${route.params.id}`); pedido.value = data } catch (e) { error.value = axios.isAxiosError(e) ? e.response?.data?.message ?? 'No se pudo cargar el pedido.' : 'No se pudo cargar el pedido.' } finally { cargando.value = false } }
async function accion(tipo: string) { try { const url = tipo === 'verificar' ? `/pedidos/${route.params.id}/pago/verificar` : `/pedidos/${route.params.id}/pago/${tipo}`; await api.post(url, tipo === 'verificar' ? { comprobanteRecibido: comprobante.value, observacion: observacion.value || undefined } : undefined); mensaje.value = 'Pedido actualizado.'; await cargar() } catch (e) { error.value = axios.isAxiosError(e) ? e.response?.data?.message ?? 'No se pudo actualizar el pago.' : 'No se pudo actualizar el pago.' } }
onMounted(cargar)
</script>
<template><section class="container py-5"><div v-if="cargando">Cargando…</div><div v-else-if="pedido" class="row justify-content-center"><div class="col-12 col-lg-7"><RouterLink to="/panel">← Volver al panel</RouterLink><div class="card border-0 shadow-sm mt-3"><div class="card-body p-4"><h1 class="h3 fw-bold">Verificar pago del pedido #{{ pedido.idPedido }}</h1><p>Cliente: {{ pedido.cliente?.nombreCompleto || pedido.cliente?.celular }}</p><p>Total: <strong>{{ Number(pedido.total).toFixed(2) }} Bs</strong></p><p>Estado: {{ pedido.estado }}</p><div v-if="pedido.estado === 'pendiente_pago'"><div class="form-check mb-3"><input id="comprobante" v-model="comprobante" class="form-check-input" type="checkbox" /><label class="form-check-label" for="comprobante">Recibí comprobante por WhatsApp</label></div><textarea v-model="observacion" class="form-control mb-3" placeholder="Observación opcional" /><button class="btn btn-success me-2" type="button" @click="accion('verificar')">Verificar pago</button><button class="btn btn-outline-danger" type="button" @click="accion('no-llego')">No llegó el pago</button></div><div v-if="pedido.estado === 'no_pagado'"><button class="btn btn-primary" type="button" @click="accion('reactivar')">Reactivar pedido</button></div><div v-if="mensaje" class="alert alert-success mt-3">{{ mensaje }}</div><div v-if="error" class="alert alert-danger mt-3">{{ error }}</div></div></div></div></div></section></template>
